<?php
namespace Modules\Ran\Reports;
class WastageReport extends AbstractRanReport{public function title():string{return 'Wastage and Recovery';}public function headings():array{return ['Date','Order','Type','Metal','Purity','Weight','Fine Weight','Value','Status'];}public function rows(array $f):array{$q=\DB::table('ran_wastage_entries as w')->leftJoin('ran_production_orders as p','p.id','=','w.production_order_id')->leftJoin('ran_metals as m','m.id','=','w.metal_id')->leftJoin('ran_purities as u','u.id','=','w.purity_id')->whereNull('w.deleted_at');$this->filter($q,$f,'w.entry_date','w');return $q->orderByDesc('w.entry_date')->get(['w.entry_date','p.order_no','w.entry_type','m.name as metal','u.name as purity','w.weight','w.fine_weight','w.value','w.status'])->map(fn($r)=>(array)$r)->all();}public function totals(array $rows):array{return ['Weight'=>array_sum(array_column($rows,'weight')),'Fine Weight'=>array_sum(array_column($rows,'fine_weight')),'Value'=>array_sum(array_column($rows,'value'))];}}
